    80  static Bool latm_dmx_sync_frame_bs(GF_BitStream *bs, GF_M4ADecSpecInfo *acfg, u32 *nb_bytes, u8 *buffer, u32 *nb_skipped)
    81  {
    82          u32 val, size;
    83          u64 pos, mux_size;
    84          if (nb_skipped) *nb_skipped = 0;
    85          if (!acfg) return 0;
    86
    87          while (gf_bs_available(bs)>3) {
    88                  val = gf_bs_read_u8(bs);
    89                  if (val!=0x56) {
    90                          if (nb_skipped) (*nb_skipped) ++;
    91                          continue;
    92                  }
    93                  val = gf_bs_read_int(bs, 3);
    94                  if (val != 0x07) {
    95                          gf_bs_read_int(bs, 5);
    96                          if (nb_skipped) (*nb_skipped) ++;
    97                          continue;
    98                  }
    99                  mux_size = gf_bs_read_int(bs, 13);
   100                  pos = gf_bs_get_position(bs);
   101                  if (mux_size>gf_bs_available(bs) ) {
   102                          gf_bs_seek(bs, pos-3);
   103                          return GF_FALSE;
   104                  }
   105
   106                  /*use same stream mux*/
   107                  if (!gf_bs_read_int(bs, 1)) {
   108                          Bool amux_version, amux_versionA;
   109
   110                          amux_version = (Bool)gf_bs_read_int(bs, 1);
   111                          amux_versionA = GF_FALSE;
   112                          if (amux_version) amux_versionA = (Bool)gf_bs_read_int(bs, 1);
   113                          if (!amux_versionA) {
   114                                  u32 i, allStreamsSameTimeFraming, numProgram;
   115                                  if (amux_version) gf_latm_get_value(bs);
   116
   117                                  allStreamsSameTimeFraming = gf_bs_read_int(bs, 1);
   118                                  /*numSubFrames = */gf_bs_read_int(bs, 6);
   119                                  numProgram = gf_bs_read_int(bs, 4);
   120                                  for (i=0; i<=numProgram; i++) {
   120                                  for (i=0; i<=numProgram; i++) {
   121                                          u32 j, num_lay;
   122                                          num_lay = gf_bs_read_int(bs, 3);
   123                                          for (j=0; j<=num_lay; j++) {
   124                                                  u32 frameLengthType;
   125                                                  Bool same_cfg = GF_FALSE;
   126                                                  if (i || j) same_cfg = (Bool)gf_bs_read_int(bs, 1);
   127
   128                                                  if (!same_cfg) {
   129                                                          if (amux_version==1) gf_latm_get_value(bs);
   130                                                          gf_m4a_parse_config(bs, acfg, GF_FALSE);
   131                                                  }
   132                                                  frameLengthType = gf_bs_read_int(bs, 3);
   133                                                  if (!frameLengthType) {
   134                                                          /*latmBufferFullness = */gf_bs_read_int(bs, 8);
   135                                                          if (!allStreamsSameTimeFraming) {
   136                                                          }
   137                                                  } else {
   138                                                          /*not supported*/
   139                                                  }
   140                                          }
   141
   142                                  }
   143                                  /*other data present*/
   144                                  if (gf_bs_read_int(bs, 1)) {
   145  //                                      u32 k = 0;
   146                                  }
   147                                  /*CRCcheck present*/
   148                                  if (gf_bs_read_int(bs, 1)) {
   149                                  }
   150                          }
   151                  }
   152
   153                  size = 0;
   154                  while (1) {
   155                          u32 tmp = gf_bs_read_int(bs, 8);
   156                          size += tmp;
   157                          if (tmp!=255) break;
   158                  }
   159                  if (gf_bs_available(bs) < size) {
   160                          gf_bs_seek(bs, pos-3);
   161                          return GF_FALSE;
   162                  }
   163
   164                  if (nb_bytes) {
   165                          *nb_bytes = (u32) size;
   166                  }
   167
   168                  if (buffer) {
   169                          gf_bs_read_data(bs, (char *) buffer, size);
   170                  } else {
   171                          while (size) {
   172                                  gf_bs_read_int(bs, 8);
   173                                  size--;
   174                          }
   175                  }
   176
   177                  /*parse amux*/
   178                  gf_bs_seek(bs, pos + mux_size);
   179
   180                  if ((gf_bs_available(bs)>2) && gf_bs_peek_bits(bs, 11, 0) != 0x2B7) {
   181                          gf_bs_seek(bs, pos + 1);
   182                          if (nb_skipped) (*nb_skipped) ++;
   183                          continue;
   184                  }
   185
   186                  return GF_TRUE;
   187          }
   188          return GF_FALSE;
   189  }
