   193  GF_Err latm_dmx_configure_pid(GF_Filter *filter, GF_FilterPid *pid, Bool is_remove)
   194  {
   195          const GF_PropertyValue *p;
   196          GF_LATMDmxCtx *ctx = gf_filter_get_udta(filter);
   197
   198          if (is_remove) {
   199                  ctx->ipid = NULL;
   200                  if (ctx->opid) {
   201                          gf_filter_pid_remove(ctx->opid);
   202                          ctx->opid = NULL;
   203                  }
   204                  return GF_OK;
   205          }
   206          if (! gf_filter_pid_check_caps(pid))
   207                  return GF_NOT_SUPPORTED;
   208
   209          ctx->ipid = pid;
   210          p = gf_filter_pid_get_property(pid, GF_PROP_PID_TIMESCALE);
   211          if (p) ctx->timescale = p->value.uint;
   212
   213          if (ctx->timescale && !ctx->opid) {
   214                  ctx->opid = gf_filter_pid_new(filter);
   215                  gf_filter_pid_copy_properties(ctx->opid, ctx->ipid);
   216                  gf_filter_pid_set_property(ctx->opid, GF_PROP_PID_UNFRAMED, NULL);
   217          }
   218
   219          return GF_OK;
   220  }
