   222  static void latm_dmx_check_dur(GF_Filter *filter, GF_LATMDmxCtx *ctx)
   223  {
   224          FILE *stream;
   225          GF_BitStream *bs;
   226          GF_M4ADecSpecInfo acfg;
   227          u64 duration, cur_dur, cur_pos, rate;
   228          s32 sr_idx = -1;
   229          const GF_PropertyValue *p;
   230          if (!ctx->opid || ctx->timescale || ctx->file_loaded) return;
   231
   232          if (ctx->index<=0) {
   233                  ctx->file_loaded = GF_TRUE;
   234                  return;
   235          }
   236
   237          p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_FILEPATH);
   238          if (!p || !p->value.string || !strncmp(p->value.string, "gmem://", 7)) {
   239                  ctx->is_file = GF_FALSE;
   240                  ctx->file_loaded = GF_TRUE;
   241                  return;
   242          }
   243          ctx->is_file = GF_TRUE;
   244
   245          stream = gf_fopen(p->value.string, "rb");
   246          if (!stream) return;
   247
   248          ctx->index_size = 0;
   249
   250          memset(&acfg, 0, sizeof(GF_M4ADecSpecInfo));
   500
   501          if (ctx->resume_from) {
   502                  gf_bs_seek(ctx->bs, ctx->resume_from-1);
   503                  ctx->resume_from = 0;
   504          }
   505
   506          if (cts == GF_FILTER_NO_TS)
   507                  prev_pck_size = 0;
   508
   509
   510          while (1) {
   511                  pos = (u32) gf_bs_get_position(ctx->bs);
   512                  u8 latm_buffer[4096];
   513                  u32 latm_frame_size = 4096;
   514                  if (!latm_dmx_sync_frame_bs(ctx->bs,&ctx->acfg, &latm_frame_size, latm_buffer, NULL)) break;
   515
   516                  if (ctx->in_seek) {
   517                          u64 nb_samples_at_seek = (u64) (ctx->start_range * GF_M4ASampleRates[ctx->sr_idx]);
   518                          if (ctx->cts + ctx->dts_inc >= nb_samples_at_seek) {
   519                                  //u32 samples_to_discard = (ctx->cts + ctx->dts_inc) - nb_samples_at_seek;
   520                                  ctx->in_seek = GF_FALSE;
   521                          }
   522                  }
   523
   524                  latm_dmx_check_pid(filter, ctx);
   525
   526                  if (!ctx->is_playing) {
   527                          ctx->resume_from = pos+1;
   528                          return GF_OK;
   529                  }
   530
   531                  if (!ctx->in_seek) {
   532                          GF_FilterSAPType sap = GF_FILTER_SAP_1;
   533
   534                          dst_pck = gf_filter_pck_new_alloc(ctx->opid, latm_frame_size, &output);
   535                          if (ctx->src_pck) gf_filter_pck_merge_properties(ctx->src_pck, dst_pck);
   536
   537                          memcpy(output, latm_buffer, latm_frame_size);
   538
   539                          gf_filter_pck_set_cts(dst_pck, ctx->cts);
   540                          gf_filter_pck_set_duration(dst_pck, ctx->dts_inc);
   541                          gf_filter_pck_set_framing(dst_pck, GF_TRUE, GF_TRUE);
   542
   543                          /*xHE-AAC, check RAP*/
   544                          if (ctx->acfg.base_object_type==GF_CODECID_USAC) {
   545                                  if (latm_frame_size && (output[0] & 0x80) && !ctx->prev_sap) {
   546                                          sap = GF_FILTER_SAP_1;
   547                                          ctx->prev_sap = GF_TRUE;
   548                                  } else {
   549                                          sap = GF_FILTER_SAP_NONE;
   550                                          ctx->prev_sap = GF_FALSE;
   551                                  }
   552                          }
   553                          gf_filter_pck_set_sap(dst_pck, sap);
   554
   555                          gf_filter_pck_send(dst_pck);
   556                  }
   557                  latm_dmx_update_cts(ctx);
   558
   559                  if (prev_pck_size) {
   560                          pos = (u32) gf_bs_get_position(ctx->bs);
   561                          if (prev_pck_size<=pos) {
   562                                  prev_pck_size=0;
   563                                  if (ctx->src_pck) gf_filter_pck_unref(ctx->src_pck);
   564                                  ctx->src_pck = pck;
   565                                  if (pck)
   566                                          gf_filter_pck_ref_props(&ctx->src_pck);
   567                          }
   568                  }
   569          }
   570
   571          if (pck) {
   572                  pos = (u32) gf_bs_get_position(ctx->bs);
   573                  assert(ctx->latm_buffer_size >= pos);
   574                  memmove(ctx->latm_buffer, ctx->latm_buffer+pos, ctx->latm_buffer_size - pos);
   575                  ctx->latm_buffer_size -= pos;
   576                  gf_filter_pid_drop_packet(ctx->ipid);
   577                  assert(!ctx->resume_from);
   578          } else {
   579                  ctx->latm_buffer_size = 0;
   580                  return latm_dmx_process(filter);
   581          }
   582          return GF_OK;
   583  }
