   585  static void latm_dmx_finalize(GF_Filter *filter)
   586  {
   587          GF_LATMDmxCtx *ctx = gf_filter_get_udta(filter);
   588          if (ctx->bs) gf_bs_del(ctx->bs);
   589          if (ctx->indexes) gf_free(ctx->indexes);
   590          if (ctx->latm_buffer) gf_free(ctx->latm_buffer);
   591  }
