   593  static const char *latm_dmx_probe_data(const u8 *data, u32 size, GF_FilterProbeScore *score)
   594  {
   595          u32 nb_frames=0;
   596          u32 nb_skip=0;
   597          GF_M4ADecSpecInfo acfg;
   598          GF_BitStream *bs = gf_bs_new(data, size, GF_BITSTREAM_READ);
   599          while (1) {
   600                  u32 nb_skipped = 0;
   601                  if (!latm_dmx_sync_frame_bs(bs, &acfg, 0, NULL, &nb_skipped)) break;
   602                  if (! GF_M4ASampleRates[acfg.base_sr_index]) {
   603                          nb_frames = 0;
   604                          break;
   605                  }
   606
   607                  if (nb_skipped) {
   608                          if (nb_skip) {
   609                                  nb_frames = 0;
   610                                  break;
   611                          }
   612                          nb_skip++;
   613                  }
   614                  nb_frames++;
   615          }
   616          gf_bs_del(bs);
   617          if (nb_frames>=2) {
   618                  *score = nb_skip ? GF_FPROBE_MAYBE_SUPPORTED : GF_FPROBE_SUPPORTED;
   619                  return "audio/aac+latm";
   620          }
   621          return NULL;
   622  }
