  1185  GF_Err gf_m4a_parse_config(GF_BitStream *bs, GF_M4ADecSpecInfo *cfg, Bool size_known)
  1186  {
  1187          u32 audio_obj_type;
  1188          memset(cfg, 0, sizeof(GF_M4ADecSpecInfo));
  1189          cfg->base_object_type = gf_bs_read_int_log(bs, 5, "base_object_type");
  1190          /*extended object type*/
  1191          if (cfg->base_object_type == 31) {
  1192                  cfg->base_object_type = 32 + gf_bs_read_int_log(bs, 6, "extended_base_object_type");
  1193          }
  1194          cfg->base_sr_index = gf_bs_read_int_log(bs, 4, "base_samplerate_index");
  1195          if (cfg->base_sr_index == 0x0F) {
  1196                  cfg->base_sr = gf_bs_read_int_log(bs, 24, "base_samplerate");
  1197          }
  1198          else {
  1199                  cfg->base_sr = GF_M4ASampleRates[cfg->base_sr_index];
  1200          }
  1201
  1202          cfg->chan_cfg = gf_bs_read_int_log(bs, 4, "channel_configuration");
  1203          if (cfg->chan_cfg) {
  1204                  cfg->nb_chan = GF_M4ANumChannels[cfg->chan_cfg - 1];
  1205          }
  1206
  1207          audio_obj_type = cfg->base_object_type;
  1208          if (cfg->base_object_type == 5 || cfg->base_object_type == 29) {
  1209                  if (cfg->base_object_type == 29) {
  1210                          cfg->has_ps = 1;
  1211                          cfg->nb_chan = 1;
  1212                  }
  1213                  cfg->has_sbr = GF_TRUE;
  1214                  cfg->sbr_sr_index = gf_bs_read_int_log(bs, 4, "sbr_samplerate_index");
  1215                  if (cfg->sbr_sr_index == 0x0F) {
  1216                          cfg->sbr_sr = gf_bs_read_int_log(bs, 24, "sbr_samplerate");
  1217                  }
  1218                  else {
  1219                          cfg->sbr_sr = GF_M4ASampleRates[cfg->sbr_sr_index];
  1220                  }
  1221                  cfg->sbr_object_type = gf_bs_read_int_log(bs, 5, "sbr_object_type");
  1222                  if (cfg->sbr_object_type==31)
  1223                          cfg->sbr_object_type = 32 + gf_bs_read_int_log(bs, 6, "audioObjectTypeExt");
  1224                  audio_obj_type = cfg->sbr_object_type;
  1225                  if (cfg->sbr_object_type==22) {
  1226                          /*ext_chan_cfg = */gf_bs_read_int_log(bs, 4, "channel_configuration");
  1227                  }
  1228          }
  1229
  1230          /*object cfg*/
  1231          switch (audio_obj_type) {
  1232          case 1:
  1233          case 2:
  1234          case 3:
  1235          case 4:
  1236          case 6:
  1237          case 7:
  1238          case 17:
  1239          case 19:
  1240          case 20:
   470          GF_M4A_LAYER3 = 34,
   471          /*! DST*/
   472          GF_M4A_DST = 35,
   473          /*! ALS*/
   474          GF_M4A_ALS = 36,
   475          /*! USAC*/
   476          GF_M4A_USAC = 42,
   477  };
